    for luQqenLk = 1, #wvwApgCD_flat do wvwApgCD_flat[luQqenLk] = 0 end
    table.clear(wvwApgCD_flat)
    wvwApgCD_flat = nil
    
    if fiDqTjae then 
        local result = fiDqTjae(...)
        decrypted = nil
        fiDqTjae = nil
        if type(result) == "function" then
            return result(...)
        else
            return result
        end
    else 
        decrypted = nil
        warn("[ecco] Boot Error (" .. "last_letter" .. "): " .. tostring(dsHIDINC)) 
    end
end
